"""Summarize mailbox letters without changing the input tree."""
import argparse
from datetime import datetime, timedelta
import json
from pathlib import Path
import re


NAME = re.compile(r"^[0-9]{8}T[0-9]{4}[-_]")
REQUIRED = ("id", "from", "to", "status", "at")
RESOLVING = {"DONE", "BLOCKED", "NEEDS-USER", "FAILED"}


def frontmatter(path):
    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except (OSError, UnicodeError):
        return None
    if not lines or lines[0] != "---":
        return None
    try:
        end = lines.index("---", 1)
    except ValueError:
        return None
    fields = {}
    for line in lines[1:end]:
        if ": " in line:
            key, value = line.split(": ", 1)
            fields[key] = value
    return fields


def candidate_paths(root):
    boxes = {}
    paths = []
    for box in sorted(root.iterdir(), key=lambda path: path.name):
        if box.name.startswith(".") or box.is_symlink() or not box.is_dir():
            continue
        inbox = box / "inbox"
        if inbox.is_symlink() or not inbox.is_dir():
            continue
        boxes[box.name] = {"inbox": {}, "done": 0}
        for where, folder in (("inbox", inbox), ("done", inbox / "done")):
            if folder.is_symlink() or not folder.is_dir():
                continue
            for path in folder.iterdir():
                if (path.name.startswith(".") or not path.name.endswith(".md")
                        or path.is_symlink() or not path.is_file()):
                    continue
                paths.append((path.relative_to(root).as_posix(), box.name, where, path))
    return boxes, sorted(paths, key=lambda item: item[0])


def summarize(root, now):
    boxes, paths = candidate_paths(root)
    bad = []
    letters = []
    seen = set()
    for relative, box, where, path in paths:
        fields = frontmatter(path)
        if fields is None:
            why = "no_frontmatter"
        elif any(not fields.get(key) for key in REQUIRED):
            why = "no_field"
        else:
            try:
                at = datetime.fromisoformat(fields["at"])
            except ValueError:
                why = "no_field"
            else:
                if at.tzinfo is None:
                    at = at.replace(tzinfo=now.tzinfo)
                if not NAME.match(path.name):
                    why = "bad_name"
                else:
                    try:
                        datetime.strptime(path.name[:13], "%Y%m%dT%H%M")
                    except ValueError:
                        why = "bad_name"
                    else:
                        if fields["id"] in seen:
                            why = "dup_id"
                        else:
                            seen.add(fields["id"])
                            letters.append((fields, at, where))
                            if where == "done":
                                boxes[box]["done"] += 1
                            else:
                                counts = boxes[box]["inbox"]
                                status = fields["status"]
                                counts[status] = counts.get(status, 0) + 1
                            continue
        bad.append({"file": relative, "why": why})
    resolved = {fields.get("re") for fields, _, _ in letters
                if fields["status"] in RESOLVING and fields.get("re")}
    open_letters = [
        {"id": fields["id"], "from": fields["from"], "to": fields["to"],
         "where": where, "age_min": (now - at) // timedelta(minutes=1)}
        for fields, at, where in letters
        if fields["status"] == "REQUEST" and fields["id"] not in resolved
    ]
    open_letters.sort(key=lambda item: (item["to"], item["id"]))
    bad.sort(key=lambda item: (item["file"], item["why"]))
    return {"v": 1, "open": open_letters, "boxes": boxes, "bad": bad}


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only mailbox summary")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("--now must be an ISO datetime with a timezone")
    if now.tzinfo is None or now.utcoffset() is None:
        parser.error("--now must have a timezone")
    if not args.folder.is_dir():
        parser.error("folder must be a directory")
    print(json.dumps(summarize(args.folder, now), ensure_ascii=False, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
